(1, 1, 'notify-refund-returns-page', 'Edit page', 'http://localhost/estatein/wp-admin/post.php?post=135&action=edit', 'actioned', '', NULL, NULL),
(160, 2, 'learn-more', 'Learn more', 'https://woocommerce.com/posts/ecommerce-shipping-solutions-guide/?utm_source=inbox_note&utm_medium=product&utm_campaign=learn-more', 'actioned', '', NULL, NULL),
